<script setup lang="ts">
import { computed, ref, watch, onBeforeUnmount, nextTick } from 'vue'
import { useLabSession } from '../session'
import { useGuide } from '../guide'
import { SYSTEM_TITLE, EXPERIMENT_TITLE } from '../curriculum'
import { DATASET, kindNames, metrics, segments, signature, strategyNames } from '../domain'
import { phases, knowledge } from '../scenario'
import SceneView from './SceneView.vue'
import SceneWorkbench from './SceneWorkbench.vue'
import StepPanel from './StepPanel.vue'
import TrendChart from './TrendChart.vue'
const props = defineProps<{ tutorial?: boolean }>()
const emit = defineEmits<{ submitted: []; practiceSubmit: [] }>()
const guide = useGuide()
const lab = useLabSession(), fileInput = ref<HTMLInputElement>(), compareIds = ref<number[]>([]), showLegacy = ref(false)

const compared = computed(() => lab.saved.trials.filter(t => !compareIds.value.length || compareIds.value.includes(t.id)))
const conclusionLabels = { mapping: '关联与错配：错误如何影响读数，如何证明修复有效？', period: '发布周期：条数、尖峰可见性和告警时刻分别说明什么？', strategy: '规则策略：误触发、延迟、切换和恢复之间如何权衡？', transfer: '独立迁移：新台账出现什么问题，你依据什么定位并修复？', limits: '结论边界：模拟数据、前端成绩和当前方案有哪些限制？' }
const formatDate = (text: string) => new Date(text).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false })
const currentReading = computed(() => lab.reading(lab.selected))
watch(() => lab.page, p => { if (p !== 'lab') lab.pause() })
onBeforeUnmount(lab.pause)
function download(text: string, name: string, mime = 'application/json') { const url = URL.createObjectURL(new Blob([text], { type: mime+';charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000) }
async function importFile(e: Event) { const f = (e.target as HTMLInputElement).files?.[0]; if (!f) return; try { if (f.size > 20_000_000) throw new Error('文件不能超过20 MB。'); const text = await f.text(); lab.importArchive(text); showLegacy.value = JSON.parse(text).version === 1 } catch (err) { lab.lastMessage = (err as Error).message }; (e.target as HTMLInputElement).value = '' }
async function printReport() { compareIds.value = []; await nextTick(); const details = Array.from(document.querySelectorAll<HTMLDetailsElement>('.core-report details')); const open = details.map(d => d.open); details.forEach(d => d.open = true); window.print(); details.forEach((d,i) => d.open = open[i]!) }
function exportReport() {
 const report = { title: '泵电流监测单元实验报告', dataset: DATASET, exportedAt: new Date().toISOString(), currentConfigAccepted: lab.currentAccepted, automatic: { score: lab.autoScore, max: 70, results: lab.results }, teacher: { score: lab.teacherScore, max: 30, current: lab.reviewValid, review: lab.saved.review }, submitted: lab.submitted, conclusions: lab.saved.conclusions, archive: lab.saved }
 download(JSON.stringify(report,null,2),'泵电流实验-报告及证据.json')
}
function submitFormal() { if(lab.submit()) emit('submitted') }
</script>
<template>
<div class="student-workspace">
  <main v-if="lab.page==='overview'" class="core-overview">
    <section class="core-hero"><div><div class="core-eyebrow">数字孪生技术与应用 · 核心实验01</div><h1>{{ SYSTEM_TITLE }}</h1><h2>泵电流监测单元的数字孪生构建与告警验证</h2><p>把正确数据关联到三维设备，用同一输入比较发布周期和告警策略。先预测、动手试验，再用证据解释结果。</p><div class="core-chips"><span>2学时 · 90分钟</span><span>配置与验证</span><span>自动70 + 教师30分</span></div><button class="btn primary" @click="lab.page='lab'">{{ lab.saved.trials.length ? '继续实验' : '进入核心实验' }} →</button></div><SceneView hero /></section>
    <section class="core-section"><h2>本例聚焦四个知识点</h2><div class="core-knowledge"><article v-for="k in knowledge" :key="k.title" class="core-card"><h3>{{ k.title }}</h3><p>{{ k.content }}</p></article></div></section>
    <section class="core-section"><h2>90分钟，做出可检查的实验结果</h2><div class="core-phase-grid"><button v-for="(p,i) in phases" :key="p.title" class="core-card core-phase-card" @click="lab.setPhase(i);lab.page='lab'"><span class="core-eyebrow">0{{ i+1 }} / {{ p.minutes }}分钟</span><h3>{{ p.title }}</h3><p>{{ p.question }}</p><strong>{{ p.output }}</strong></button></div></section>
    <section class="core-card core-boundary"><h2>建设进度与使用边界</h2><p>本例已实现对象关联、设备数据与规则仿真、周期与规则对照、事件处置和证据报告。完整课程仍为8学时、28步规划；数据治理、缓存补传、状态机编辑和AI专项评测待建设。</p><p>自建三维模型、教学模拟数据，不连接生产设备。本地提示不是大模型。浏览器记录不具备服务端身份认证或防作弊能力。</p><div class="core-actions"><a href="/实验指导.md" target="_blank" rel="noopener">实验指导</a><a href="/教师评分表.md" target="_blank" rel="noopener">教师评分表</a><a href="/试教记录表.md" target="_blank" rel="noopener">五人试教记录表</a><a href="/三维工厂工作区说明.md" target="_blank" rel="noopener">三维工厂工作区说明</a><a href="/操作引导与师生端说明.md" target="_blank" rel="noopener">操作引导与师生端说明</a></div></section>
  </main>
  <main v-else-if="lab.page==='lab'" class="core-workbench">
    <div class="core-lab-heading compact-lab-title"><h1>泵电流监测单元</h1><span v-if="!tutorial" class="core-score">证据 {{ lab.autoScore }}/70 · {{ lab.reviewValid?'教师 '+lab.teacherScore+'/30':'待批阅' }}</span><span v-else class="scene-practice-badge">独立演练 · 不计分</span></div>
    <div class="core-lab-grid"><div class="core-lab-main">
      <SceneWorkbench />
      <section class="core-card"><div class="core-replay-title"><h2>资产数据与事件时间</h2><strong>{{ currentReading ? currentReading.value+' '+currentReading.unit : '—' }}</strong></div><p :class="currentReading && !currentReading.valid?'core-warning':'core-small'">{{ currentReading?.quality ?? '等待有效发布数据' }} · 资产读数按当前配置预览；下图保留试验的锁定配置。</p><TrendChart /></section>
      <section class="core-card"><h2>固定输入与教学标注</h2><div class="core-segments"><div v-for="s in segments" :key="s.start"><strong>{{ s.start }}—{{ s.end }}s</strong><span>{{ s.name }}</span><small>{{ s.truth?'教学事件持续中':'非目标事件' }}</small></div></div><p class="core-small">11—34秒标注为同一教学事件。误触发按该段之外的触发计数；检测延迟从第11秒起算。标注用于技术验证，不是实际设备故障判断。</p></section>
      <section class="core-card"><h2>检测输出与人工事件处置</h2><p class="core-small">检测器继续处理每个样本；未确认或待关闭事件不会屏蔽下一次越限。</p><p>检测信号：{{ lab.active?.detector.active ? '越限中' : '未激活' }} · {{ lab.active?.detections.map(e=>e.tick+'s '+(e.type==='trigger'?'触发':'恢复')).join('；') || '尚无事件' }}</p><div class="table-scroll"><table><thead><tr><th>事件</th><th>触发</th><th>恢复</th><th>确认</th><th>关闭</th><th>操作</th></tr></thead><tbody><tr v-for="e in lab.active?.incidents" :key="e.id"><td>#{{ e.id }}</td><td>{{ e.triggeredAt }}s</td><td>{{ e.recoveredAt === null?'未恢复':e.recoveredAt+'s' }}</td><td>{{ e.acknowledgedAt === null?'待确认':e.acknowledgedAt+'s' }}</td><td>{{ e.closedAt === null?'待关闭':e.closedAt+'s' }}</td><td><button class="core-link" :disabled="e.acknowledgedAt!==null" @click="lab.acknowledge(e.id)">确认事件{{ e.id }}</button><button class="core-link" :disabled="e.closedAt!==null" @click="lab.closeIncident(e.id)">复核关闭{{ e.id }}</button></td></tr></tbody></table></div></section>
      <section v-if="!tutorial" class="core-card"><h2>实验证据进度</h2><div v-for="r in lab.results" :key="r.id" class="core-achievement"><div><strong>{{ r.title }}</strong><p>{{ r.detail }}</p><small>证据：{{ r.trialIds.map(id=>'#'+id).join('、') || '尚未满足' }}</small></div><b>{{ r.earned }}/{{ r.max }}</b></div><button class="btn" @click="lab.page='report'">查看对照表与填写结论 →</button></section>
    </div><StepPanel :tutorial="tutorial" /></div>
  </main>
  <main v-else class="core-report">
    <div class="core-lab-heading"><div><div class="core-eyebrow">从配置快照到可复现证据</div><h1>实验报告</h1><p>泵电流监测单元的数字孪生构建与告警验证</p></div><div v-if="!tutorial" class="core-actions no-print"><button class="btn" @click="fileInput?.click()">导入备份</button><button class="btn" @click="download(lab.exportJson(),'泵电流实验-v2备份.json')">导出备份</button><button class="btn" @click="exportReport">导出报告与证据</button><button class="btn primary" @click="printReport">打印报告</button></div></div>
    <section v-if="!tutorial" class="core-card"><div class="core-report-summary"><strong>{{ lab.totalScore }}<small>/100</small></strong><div><p>自动实验证据 {{ lab.autoScore }}/70 · 教师论证 {{ lab.reviewValid ? lab.teacherScore+'/30' : '待复核 / 30' }}</p><p>报告：{{ lab.submitted?'已提交':'未提交或证据已变化' }} · 当前配置：{{ lab.currentAccepted?'已验收':'待复验' }}</p><p class="core-small">{{ DATASET }} · 全部试验均使用1—40秒输入。历史达成保留，当前方案须单独验收；文字内容不自动得论证分。</p></div></div><p class="core-small">本地教师录分仅作试教记录，不构成身份认证或可信服务端成绩。</p></section>
    <section class="core-card"><h2>同输入实验对照</h2><p>选择试验并排比较；配置差异须与研究变量一致。恢复时刻仅统计35秒后恢复。</p><div class="core-compare-choices no-print"><label v-for="t in lab.saved.trials" :key="t.id"><input v-model="compareIds" type="checkbox" :value="t.id" />#{{ t.id }} {{ kindNames[t.kind] }}</label><button class="core-link" @click="compareIds=[]">显示全部</button></div><div class="table-scroll"><table><thead><tr><th>仿真记录 / 类型</th><th>配置与完整性</th><th>发布数 / 尖峰可见</th><th>误触发 / 检测延迟</th><th>切换 / 恢复时刻</th><th>源触发 / 恢复</th></tr></thead><tbody><tr v-for="t in compared" :key="t.id"><td>#{{ t.id }} {{ kindNames[t.kind] }}</td><td>{{ strategyNames[t.config.strategy] }} · {{ t.config.period }}s<br>{{ t.complete?'完整40秒':t.tick+'秒 · 未完成' }} · 场景{{ t.sceneRevision??0 }}<br>{{ signature(t.config)===signature(lab.saved.config)&&(t.sceneRevision??0)===lab.sceneLayout.revision?'与当前一致':'历史配置' }}</td><td>{{ metrics(t).published }} / {{ metrics(t).visibleSpike?'可见':'未见' }}</td><td>{{ metrics(t).falseTriggers }} / {{ metrics(t).delay===null?'未检出':metrics(t).delay+'s' }}</td><td>{{ metrics(t).switches }} / {{ metrics(t).recoveryAt===null?'—':metrics(t).recoveryAt+'s' }}</td><td>{{ t.detections.map(e=>e.tick+'s'+(e.type==='trigger'?'↑':'↓')).join(' ') || '无' }}</td></tr></tbody></table></div><p v-if="!lab.saved.trials.length">暂无试验记录，配置正确本身不计实验分。</p></section>
    <section v-if="!tutorial" class="core-card"><h2>评分依据</h2><div v-for="r in lab.results" :key="r.id" class="core-achievement"><div><strong>{{ r.title }}</strong><p>{{ r.detail }}</p><small>试验 {{ r.trialIds.join('、') || '待完成' }}</small></div><b>{{ r.earned }}/{{ r.max }}</b></div></section>
    <section v-if="!tutorial" class="core-card"><h2>实验结论与适用边界</h2><p>引用试验编号和实测数字，说明预测是否成立、哪项证据支持结论。字数仅用于提交完整性，不自动计分。</p><label v-for="(label,key) in conclusionLabels" :key="key" class="field"><span>{{ label }}</span><textarea v-model="lab.saved.conclusions[key]" :aria-label="label" rows="3" maxlength="20000" class="no-print" /><p class="print-only core-conclusion">{{ lab.saved.conclusions[key] || '尚未填写' }}</p></label><button class="btn primary no-print" @click="submitFormal">提交报告等待教师复核</button><p v-if="lab.saved.review && !lab.reviewValid" class="core-warning">证据或结论已变更，旧教师评价保留供追溯，但不计入当前总分。请重新提交并复核。</p></section>
    <section v-if="tutorial" class="core-card" data-guide="practice-conclusion"><h2>演练结论</h2><p>比较错误与修复后的两轮记录，用自己的话解释变化。这里只练习流程，不代替完整实验报告。</p><label class="field"><span>演练结论</span><textarea v-model="lab.saved.conclusions.mapping" aria-label="演练结论" rows="4" maxlength="20000" /></label><div data-guide="practice-submit"><button class="btn primary" @click="emit('practiceSubmit')" :disabled="guide.step<10 || guide.completed">{{ guide.completed?'演练已提交':'提交演练' }}</button><p>仅保存在独立演练实例，不计成绩，不进入教师批阅。</p></div></section>
    <section class="core-card"><h2>实例场景结构 · 修订{{ lab.sceneLayout.revision }}</h2><p>提交报告会冻结该结构。场景显示名称、归属及模型稳定身份均可追溯。</p><details><summary>查看场景结构快照</summary><pre>{{ JSON.stringify(lab.sceneLayout,null,2) }}</pre></details></section>
    <section class="core-card"><h2>逐轮仿真证据</h2><details v-for="t in lab.saved.trials" :key="t.id" class="core-trial-detail"><summary>#{{ t.id }} {{ kindNames[t.kind] }} · {{ strategyNames[t.config.strategy] }} · {{ t.tick }}/40秒</summary><div><p><b>数据版本：</b>{{ t.dataset }} · 场景修订{{ t.sceneRevision ?? 0 }} / {{ formatDate(t.startedAt) }} / {{ t.complete?'完整':'未完成' }}</p><p><b>运行前预测：</b>{{ t.prediction }}</p><p v-for="(edit,i) in t.predictionHistory" :key="i" class="core-small">预测修订{{ i+1 }} · {{ formatDate(edit.at) }} · {{ edit.text }}</p><pre>{{ JSON.stringify(t.config,null,2) }}</pre><p v-for="(o,i) in t.observations" :key="i">观察{{ i+1 }}：源{{ o.tick }}s（{{ o.sourceValue ?? '—' }}），发布{{ o.displayTick ?? o.tick }}s · {{ o.model }}模型 → {{ o.code || '未绑定' }} → {{ o.field || '无字段' }} → {{ o.value ?? '—' }} {{ o.unit }} · {{ o.quality }}<br>{{ o.note }}</p><p v-if="!t.observations.length">尚未保存观察，此试验不计实验证据分。</p><p>检测：{{ t.detections.map(e=>e.tick+'s '+e.type).join('；') || '无' }}</p><p v-for="e in t.incidents" :key="e.id">事件{{ e.id }}：触发{{ e.triggeredAt }}s；确认{{ e.acknowledgedAt ?? '—' }}；恢复{{ e.recoveredAt ?? '—' }}；关闭{{ e.closedAt ?? '—' }}</p><div class="core-actions no-print"><button class="btn" @click="lab.selectTrial(t.id);lab.page='lab'">查看此仿真记录</button><button class="btn" @click="lab.repeatTrial(t.id);lab.page='lab'">按此配置重新仿真</button></div></div></details></section>
    <section v-if="!tutorial" class="core-card"><h2>教师反馈</h2><p v-if="!lab.saved.review">{{ lab.submitted ? '报告已提交，可在教师端演示中选择本版本进行批阅。' : '完成报告并提交后，才能进入本地批阅列表。' }}</p><div v-else><p>{{ lab.saved.review.reviewer }} · {{ formatDate(lab.saved.review.at) }} · {{ lab.reviewValid?'当前版本有效':'历史版本反馈，不计当前分数' }}</p><p>解释与证据 {{ lab.saved.review.explanation }}/20；边界 {{ lab.saved.review.limits }}/10</p><p>{{ lab.saved.review.feedback }}</p></div></section>
    <section class="core-card"><h2>配置变更与复测记录</h2><details v-for="(entry,i) in lab.saved.logs" :key="i"><summary>{{ formatDate(entry.at) }} · {{ entry.text }}</summary><div v-if="entry.before || entry.sceneBefore"><h4>变更前</h4><pre>{{ JSON.stringify(entry.before ?? entry.sceneBefore,null,2) }}</pre><h4>变更后</h4><pre>{{ JSON.stringify(entry.after ?? entry.sceneAfter,null,2) }}</pre></div></details></section>
  </main>
  <footer v-if="!tutorial" class="core-footer"><span>{{ lab.persistenceError || '本地自动保存 · v1存档保留只读 · 不连接生产设备' }}</span><button v-if="lab.legacy" class="core-link" @click="showLegacy=true">查看v1只读存档</button><button class="core-link" @click="fileInput?.click()">导入v1/v2备份</button><button class="core-link" @click="download(lab.exportJson(),'泵电流实验-v2备份.json')">导出v2备份</button></footer>
  <input ref="fileInput" type="file" accept=".json,application/json" class="hidden" @change="importFile" />
  <div v-if="lab.lastMessage && !(tutorial&&(guide.step===5||guide.step===8))" class="core-toast" role="status"><span>{{ lab.lastMessage }}</span><button aria-label="关闭通知" @click="lab.lastMessage=''">×</button></div>
  <div v-if="showLegacy && lab.legacy" class="modal-backdrop" @click.self="showLegacy=false"><section class="modal core-legacy" role="dialog" aria-modal="true" aria-label="v1只读存档"><h2>v1只读存档</h2><p>旧配置和成绩不转为v2得分，原始v1浏览器存储保持保留。</p><p v-for="(a,i) in lab.legacy.assets" :key="i">{{ a.name }} · {{ a.code }}</p><p>{{ lab.legacy.reflection }}</p><div class="core-legacy-events"><p v-for="(e,i) in lab.legacy.events" :key="i">{{ e.tick }}s · {{ e.text }}</p></div><div class="core-actions"><button class="btn" @click="download(lab.legacy!.raw,'数字孪生实验-v1原始备份.json')">导出v1原始存档</button><button class="btn primary" @click="showLegacy=false">关闭只读存档</button></div></section></div>
</div>
</template>


